  palm.rotation.z=side*.10;
  ellipsoid(hand,'wrist',v(0,.16,-.015),[.082,.125,.082],handMaterial);
  const spreads=[-.083,-.025,.039,.096];
  const lengths=[.255,.33,.305,.225];
  const fingers=[];
  for(let i=0;i<4;i++){
    const len=lengths[i],radius=i===3?.029:.035;
    const base=group(['index-finger','middle-finger','ring-finger','little-finger'][i],
      hand,v(side*spreads[i],-.11,.026));
    phalanx(base,'proximal-phalanx',len*.43,radius);
    const middle=group('middle-joint',base,v(0,-len*.43,0));
