    [-1,0,0,0,0],
    [-.985,distal*.78,distal*.78,0,0],
    [-.90,distal,distal,0,0],
    [-.65,distal*.72+proximal*.28,distal*.72+proximal*.28,0,0],
    [-.30,proximal*.96,proximal*.96,0,0],
    [-.10,proximal,proximal,0,0],
    [-.025,proximal*.74,proximal*.74,0,0],
    [0,0,0,0,0]
  ];
  return surfaceMesh(parent,name,profileSurface(profile),(p,theta)=>{
    if(!forearm)return color(0xf6bc18).lerp(color(0xe8ad11),-p.y*.45);
    const progress=-p.y;
    const c=color(0xe8b11d);
    c.lerp(color(0xa08c31),clamp((progress-.5)/.4,0,1)*.65);
    return c.lerp(color(0x55503a),clamp((progress-.8)/.2,0,1)*.86);
  },32,20);
}
