function poseArm(rig,p){
  const elbow=v(...p.e),palm=v(...p.h);
  const handQ=new THREE.Quaternion().setFromEuler(new THREE.Euler(...p.r,'XYZ'));
  const wrist=palm.clone().add(v(0,.17*p.sz,-.015*p.sz).applyQuaternion(handQ));
  const upperVector=elbow.clone().sub(rig.shoulder);
  const upperLength=upperVector.length();
  const upperQ=new THREE.Quaternion().setFromUnitVectors(down,upperVector.normalize());
  const lowerVector=wrist.clone().sub(elbow);
  const lowerLength=lowerVector.length();
  const lowerQ=new THREE.Quaternion().setFromUnitVectors(down,lowerVector.normalize());
  rig.arm.quaternion.copy(upperQ);
  rig.upper.scale.set(1,upperLength,1);
  rig.lower.position.set(0,-upperLength,0);
  rig.lower.quaternion.copy(upperQ).invert().multiply(lowerQ);
  rig.lowerMesh.scale.set(1,lowerLength,1);
  const inverseLower=lowerQ.clone().invert();
  rig.hand.group.position.copy(palm.sub(elbow).applyQuaternion(inverseLower));
  rig.hand.group.quaternion.copy(inverseLower).multiply(handQ);
  rig.hand.group.scale.setScalar(p.sz);
  rig.hand.fingers.forEach((f,i)=>{
    f.base.rotation.set(-(.10+p.c*.78),0,rig.hand.side*(i-1.45)*.16*p.sp);
    f.middle.rotation.set(-(.13+p.c*1.05),0,0);
    f.tip.rotation.set(-(.12+p.c*.78),0,0);
  });
  rig.hand.thumb.rotation.set(-p.c*.65,0,-rig.hand.side*(.62+.18*p.sp));
  rig.hand.thumbTip.rotation.set(-p.c*.75,0,rig.hand.side*.38);
}

