  let f=(t-a.t)/(b.t-a.t);
  f=f*f*(3-2*f);
  return mix(a,b,f);
}

function render(t=0){
  const time=Number.isFinite(t)?((t%PERIOD)+PERIOD)%PERIOD:0;
  const p=sample(time);
  character.position.set(p.x,p.y,0);
  character.rotation.set(p.pitch,p.yaw,p.lean,'YXZ');
  character.scale.setScalar(p.s);
  head.rotation.set(...p.hr,'YXZ');
  leftLeg.rotation.set(p.lg[0],0,p.lg[1]);
  rightLeg.rotation.set(p.lg[2],0,p.lg[3]);
  poseArm(leftArm,p.L);
  poseArm(rightArm,p.R);
  for(const e of eyeRigs){
    e.opening.scale.y=p.eye;
    e.upper.position.y=.018+.105*p.eye;
    e.lower.position.y=-.018-.104*p.eye;
    e.brow.position.y=.060+.112*p.eye;
  }
  mouthLine.morphTargetInfluences[0]=Math.max(0,p.smile);
  mouthLine.morphTargetInfluences[1]=Math.max(0,-p.smile);
  lowerLip.position.y=-.043-.038*p.smile;
  renderer.render(scene,ref);
}

window.nwb={
  scene,renderer,cameras:{ref},characters:[character],render,ready:true
};
